CREATE TABLE roles (id BIGSERIAL PRIMARY KEY, name VARCHAR(40) NOT NULL UNIQUE);
CREATE TABLE users (id BIGSERIAL PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE user_roles (user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, role_id BIGINT NOT NULL REFERENCES roles(id), PRIMARY KEY(user_id, role_id));
INSERT INTO roles(name) VALUES ('ADMIN'), ('SUPER_ADMIN') ON CONFLICT DO NOTHING;
CREATE TABLE hero (id BIGSERIAL PRIMARY KEY, eyebrow VARCHAR(180) NOT NULL, headline VARCHAR(500) NOT NULL, subheadline TEXT NOT NULL, primary_action VARCHAR(120) NOT NULL, secondary_action VARCHAR(120) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE hero_metrics (id BIGSERIAL PRIMARY KEY, hero_id BIGINT NOT NULL REFERENCES hero(id) ON DELETE CASCADE, label VARCHAR(100) NOT NULL, value VARCHAR(40) NOT NULL, display_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE services (id BIGSERIAL PRIMARY KEY, title VARCHAR(180) NOT NULL, slug VARCHAR(180) NOT NULL UNIQUE, description TEXT NOT NULL, icon VARCHAR(50) NOT NULL, technologies JSONB NOT NULL DEFAULT '[]', display_order INTEGER NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE technologies (id BIGSERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, category VARCHAR(60) NOT NULL, logo_url TEXT, display_order INTEGER NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE case_studies (id BIGSERIAL PRIMARY KEY, title VARCHAR(220) NOT NULL, industry VARCHAR(100) NOT NULL, challenge TEXT NOT NULL, solution TEXT NOT NULL, technologies JSONB NOT NULL DEFAULT '[]', display_order INTEGER NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE case_study_results (id BIGSERIAL PRIMARY KEY, case_study_id BIGINT NOT NULL REFERENCES case_studies(id) ON DELETE CASCADE, label VARCHAR(100) NOT NULL, value VARCHAR(50) NOT NULL, display_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE industries (id BIGSERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, description TEXT NOT NULL, icon VARCHAR(50) NOT NULL, display_order INTEGER NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE testimonials (id BIGSERIAL PRIMARY KEY, quote TEXT NOT NULL, client_name VARCHAR(160) NOT NULL, client_role VARCHAR(180) NOT NULL, company VARCHAR(180) NOT NULL, company_logo_url TEXT, rating SMALLINT NOT NULL CHECK (rating BETWEEN 1 AND 5), display_order INTEGER NOT NULL DEFAULT 0, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE capabilities (id BIGSERIAL PRIMARY KEY, title VARCHAR(140) NOT NULL, description TEXT NOT NULL, skills JSONB NOT NULL DEFAULT '[]', percentage INTEGER NOT NULL CHECK (percentage BETWEEN 0 AND 100), display_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE process_steps (id BIGSERIAL PRIMARY KEY, title VARCHAR(100) NOT NULL, description TEXT NOT NULL, duration VARCHAR(60) NOT NULL, display_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE contact_leads (id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, company VARCHAR(160), email VARCHAR(254) NOT NULL, phone VARCHAR(40), required_service VARCHAR(120) NOT NULL, budget VARCHAR(60), timeline VARCHAR(60), description VARCHAR(5000) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'NEW', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_contact_leads_status_created ON contact_leads(status, created_at DESC);
CREATE TABLE site_content (content_key VARCHAR(60) PRIMARY KEY, payload JSONB NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_by BIGINT REFERENCES users(id));
